head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCells]<br/>Body 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "'bycolrec' 설정 시 'bycol' 방식으로 병합 후 'byrow' 방식으로 2차 병합을 수행합니다. ('byrow' 방식으로 2차 병합 시 각 Column 의 병합 상태가 같아야 합니다.)",
        "'byrowrec' 설정 시 'byrow' 방식으로 병합 후 'bycol' 방식으로 2차 병합을 수행합니다. ('bycol' 방식으로 2차 병합 시 각 Row 의 병합 상태가 같아야 합니다.)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_mergeCells : bycolrec / byrowrec enum (getValue) — '' 미설정(병합 안함) / 'bycolrec' / 'byrowrec'
    let vMerge = con_mergeCells.getValue();

    // mergeCells 2차 병합이 보이도록 설계한 데이터
    //  - 좌상단 2x2 블록(col1,col2 / row0,row1) = 동일값 'A'
    //      → bycolrec : bycol 로 각 Column 세로병합(rowSpan2) 후 byrow 로 2차 가로병합 → rowSpan2 + colSpan2 셀 생성
    //      → byrowrec : byrow 로 각 Row 가로병합(colSpan2) 후 bycol 로 2차 세로병합 → rowSpan2 + colSpan2 셀 생성
    //  - 우측 col3,col4 / 전 row = 동일값 'C'
    //      → 4행 x 2열 전부 'C' → 2차 병합으로 rowSpan4 + colSpan2 셀 생성
    let properties = {
        dataList: "data:dlt_bind",
    };

    // mergeCells : 미설정('') 이면 속성 자체를 추가하지 않음(병합 안함)
    if (vMerge === 'bycolrec') {
        properties.mergeCells = 'bycolrec';
    } else if (vMerge === 'byrowrec') {
        properties.mergeCells = 'byrowrec';
    }

    let lblDesc = 'mergeCells=' + (vMerge === '' ? '(미설정)' : vMerge);

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + ' / 2x2 블록 4개 : (col1,col2 × row0,row1)=A, (col3,col4 × row0,row1)=C, (col1,col2 × row2,row3)=B, (col3,col4 × row2,row3)=D"', '', 'label1');

    // dataList 생성 (4행) 후 2차 병합 확인용 데이터로 치환
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    let mergeData = [
        { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
        { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
        { "col1": "B", "col2": "B", "col3": "D", "col4": "D" },
        { "col1": "B", "col2": "B", "col3": "D", "col4": "D" }
    ];
    dlt_bind.setJSON(mergeData, false);

    // target 생성 (병합 후에도 스크롤이 생기지 않도록 4행 내용에 맞는 높이로 로컬 생성)
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();
    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" style="width:560px;height:200px;">';
    s += '<w2:caption style="" id="caption1" value="mergeCells 2차 병합 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 병합 상태 확인 : Body 영역의 각 td 에 대해 rowSpan / colSpan 을 읽어
//   1차 병합(한 방향만 span>1) 과 2차 병합(rowSpan>1 AND colSpan>1) 결과를 출력한다.
//  - mergeCells 는 동일한 값이 연속되는 Cell 을 td 의 rowSpan/colSpan 으로 병합한다.
//  - 2차 병합이 적용되면 하나의 td 가 rowSpan>1 과 colSpan>1 을 동시에 가진다.
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] mergeCells : " + (target1.options.mergeCells || "(미설정)"));

    // Body 영역 td (rownum/checkbox 등 부가 td 제외, 데이터 셀만)
    let bodyTds = document.querySelectorAll("td[id*='target1_cell_']");
    if (bodyTds.length === 0) {
        bottom.setReturnValue("Body Cell(td) 을 찾을 수 없습니다.");
        return;
    }

    let recCount = 0;
    let descs = [];
    for (let i = 0; i < bodyTds.length; i++) {
        let td = bodyTds[i];
        // display:none 처리된(병합으로 흡수된) 셀은 제외
        if (getComputedStyle(td).display === "none") continue;

        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        if (rs <= 1 && cs <= 1) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        let r = m ? Number(m[1]) : 0, c = m ? Number(m[2]) : 0;
        let val = (td.textContent || "").trim();
        if (rs > 1 && cs > 1) {
            recCount++;
            descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록(2차)병합(" + rs + "x" + cs + ") = '" + val + "'");
        } else if (rs > 1) {
            descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
        } else {
            descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
        }
    }
    bottom.setReturnValue("병합 그룹 " + descs.length + "개 (2차 블록병합 " + recCount + "개)");
    if (descs.length === 0) bottom.setReturnValue("병합된 셀 없음");
    else for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
}
